import {STUDIO_TEMPLATES,nextStudioProduct,studioGoal} from './product-lab.js';
import {goodsFor,pendingProduction,finishedCapacity,finishedOccupancy,productionPlan} from './creations.js';
import {FILAMENT_COLORS,colorFor,filamentStock,compatiblePrinters,specFor,STATUS} from './model.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>n.toLocaleString('fr-FR',{style:'currency',currency:'EUR'});
const time=n=>n<60?Math.round(n)+' min':(n/60).toLocaleString('fr-FR',{maximumFractionDigits:1})+' h';
const count=n=>n.toLocaleString('fr-FR',{maximumFractionDigits:0});
export function creationPicture(id,color='#a6b98d'){
 const shapes={
  'key-tag':'<path d="M33 28h35l14 21-25 26-30-19V34z"/><circle cx="41" cy="39" r="5" fill="#f6e8c7"/><path d="m54 46 13 9-10 10-13-9z" fill="#f0d8ae"/>',
  coaster:'<path d="m21 49 33-22 36 21-34 25z"/><path d="m28 49 27-16 27 15-26 18z" fill="none" stroke="#e6d8ab" stroke-width="3"/><path d="m34 44 32 16m-22-22 32 16m-25-20 30 16M35 56l28-20m-18 26 28-20" stroke="#e6d8ab" stroke-width="2"/>',
  'phone-dock':'<path d="m33 30 24-9 15 40-30 13-13-8 22-9z"/><path d="m39 30 14-5 10 26-16 6z" fill="#eee0b7"/><path d="m30 66 13 9 31-13 2 5-32 14-16-10z"/>',
  'modular-tray':'<path d="m16 39 49-18 33 24v23L46 86 16 62z"/><path d="m23 41 42-14 25 19-43 16z" fill="#e8d6aa"/><path d="M46 62v17M37 36l30 20m-15-25 28 20" fill="none" stroke="#a18d63" stroke-width="3"/>',
  'plant-labels':'<path d="m25 31 26-9 18 11-27 10zM42 43v38l8-2V40zM61 51l26-9 18 11-27 10zM78 63v24l7-2V60z"/><path d="m34 32 15-5m20 26 14-5" stroke="#f5e6bd" stroke-width="3"/>',
  'desk-vase':'<path d="M35 22q22-10 37 0l-6 15q-2 10 15 23 10 21-26 24-34-2-24-22 18-18 11-27z"/><ellipse cx="54" cy="22" rx="19" ry="5" fill="#e5d5ac"/><path d="M48 35q13 14-6 35m16-36q-7 20 4 40" fill="none" stroke="#eadbbe" stroke-width="2"/>',
  'wall-organizer':'<path d="m23 31 59-16v56L23 88z"/><path d="m31 49 19-6 8 5v18l-19 6-8-5zm29-8 13-4 9 6v25l-14 4-8-5z" fill="#eee0b7"/><path d="m29 37 45-13" stroke="#d1dbb6" stroke-width="4"/>',
 };
 return `<svg viewBox="0 0 115 100" aria-hidden="true"><ellipse cx="59" cy="85" rx="39" ry="6" fill="#8e8159" opacity=".13"/><g fill="${color}" stroke="#8e9471" stroke-width="1.3" stroke-linejoin="round">${shapes[id]||shapes['modular-tray']}</g><path d="m88 14 2 5 5 2-5 2-2 5-2-5-5-2 5-2z" fill="#cfad73" stroke="none"/></svg>`;
}
export function creationsPanel(s,tab='design'){
 const pending=s.orders.find(o=>o.id===s.studio.pending),ready=goodsFor(s),jobs=pendingProduction(s),current=nextStudioProduct(s,'design');
 return `<header><div><span class="eyebrow">LES IDÉES DEVIENNENT DES OBJETS</span><h2>Mes créations <em>✦</em></h2></div><button data-action="creations-panel" aria-label="Fermer les créations">×</button></header><div class="creations-tabs"><button data-action="creations-tab" data-tab="design" aria-pressed="${tab==='design'}">Concevoir</button><button data-action="creations-tab" data-tab="production" aria-pressed="${tab==='production'}">Produire & vendre <b>${ready}</b></button></div><div class="creations-content"><div class="creation-score"><div><b>${ready}</b><span>objets prêts</span></div><div><b>${jobs.length}</b><span>en fabrication</span></div><div><b>${s.studio.stats.sold}</b><span>vendus du stock</span></div></div>${pending?`<div class="prototype-notice"><b>✦ Prototype · ${esc(pending.prototypeMeta.name)}</b><span>${STATUS[pending.status]} · ${pending.grams} g · ${time(pending.hours*60)} d’impression de référence</span><small>Le contrôle et les photos valident la création ; ce prototype ne sera pas revendu.</small></div>`:''}${tab==='design'?designCards(s,current):productionCards(s)}<p class="creation-footnote">Les durées, recettes et prix de ces projets sont des hypothèses de jeu. Fabriquer consomme du filament, de l’électricité et du temps. Le revenu arrive seulement après une vraie commande livrée.</p></div>`;
}
function designCards(s,current){
 const projects=STUDIO_TEMPLATES.filter(t=>t.origin==='original').sort((a,b)=>a.creationMinutes-b.creationMinutes);
 return `<div class="creation-intro"><h3>Un projet pour chaque temps libre.</h3><p>Choisis ton objet. La conception avance sur tes heures disponibles, puis un prototype doit être imprimé et contrôlé.</p></div><div class="creation-path"><span>① Concevoir</span><i>→</i><span>② Prototyper</span><i>→</i><span>③ Fabriquer</span><i>→</i><span>④ Vendre</span></div><div class="design-cards">${projects.map(t=>{
  const done=s.studio.products.some(p=>p.id===t.id),active=current?.id===t.id&&s.studio.idleMode==='design',progress=active?s.studio.progress.design:s.studio.workById[t.id]||0,compatible=compatiblePrinters(s,{...t,minQuality:.96}).length;
  return `<article class="design-card ${active?'is-active':''} ${done?'is-validated':''}"><div class="creation-drawing" style="--creation-color:${t.color}">${creationPicture(t.id,t.color)}<span>${done?'✓ Validé':t.creationMinutes<=90?'PETIT PROJET':t.creationMinutes>=480?'GRANDE IDÉE':'À FAÇONNER'}</span></div><div class="design-card-copy"><h3>${esc(t.name)}</h3><strong>${time(t.creationMinutes)} <small>de conception</small></strong><p>${t.grams} g ${t.material.toUpperCase()} · ${time(t.hours*60)} par exemplaire</p><div class="design-card-meta"><span>Prototype ${t.prototypeGrams||45} g</span><b>Repère ${euro(t.price)}</b></div>${!done&&progress?`<div class="studio-progress"><i style="width:${Math.min(100,progress/t.creationMinutes*100)}%"></i></div><small class="creation-work">${time(progress)} déjà consacrés au projet</small>`:''}${!compatible&&!done?`<small class="creation-warning">Volume requis : ${t.dimensions.join(' × ')} mm. Prévois une machine adaptée.</small>`:''}${done?'<button class="button secondary small" data-action="creations-tab" data-tab="production">Produire cette création →</button>':`<button class="button ${active?'secondary':'primary'} small" data-action="start-creation" data-id="${t.id}" ${s.studio.pending?'disabled':''}>${active?'Conception en cours':'Concevoir · '+time(t.creationMinutes)}</button>${active?'<button class="text-button creation-customize" data-action="project-draft">Nommer & fixer mon prix</button>':''}`}</div></article>`;
 }).join('')}</div>`;
}
function productionCards(s){
 if(!s.studio.products.length)return `<div class="creation-empty"><span>✦</span><h3>La première idée attend de prendre forme.</h3><p>Conçois un objet et valide son prototype. Tu pourras ensuite remplir ta petite boutique.</p><button class="button primary" data-action="creations-tab" data-tab="design">Choisir un projet</button></div>`;
 const production=pendingProduction(s),space=finishedOccupancy(s),capacity=finishedCapacity(s);
 return `<div class="creation-intro"><h3>Produire avant la prochaine commande.</h3><p>Fabrique de petites séries entre deux clients. Les pièces prêtes peuvent être vendues directement ; les surplus restent en stock.</p></div><div class="finished-space"><span>Place réservée dans l’atelier</span><b>${space} / ${capacity}</b><div><i style="width:${Math.min(100,space/capacity*100)}%"></i></div><small>Pièces prêtes + fabrications prévues. Un rayonnage ajoute 8 places. ${time(s.studio.stats.machineMinutes)} machine consacrées au stock.</small></div><div class="product-cards">${s.studio.products.map(p=>{
  const plan=productionPlan(s,p.id),pending=production.filter(o=>o.product===p.id),lots=s.studio.stock.filter(l=>l.productId===p.id),stock=goodsFor(s,p.id),available=filamentStock(s,p.material,plan.colorId),machines=compatiblePrinters(s,{...p,minQuality:.9}),fastest=machines.length?Math.min(...machines.map(m=>p.hours*specFor(m).speed)):null;
  return `<article class="product-card"><div class="product-card-top"><div class="product-card-picture">${creationPicture(p.id,p.color)}</div><div><span class="creation-origin">${p.origin==='original'?'Création originale':'Licence commerciale simulée · hors Etsy'}</span><h3>${esc(p.name)}</h3><div class="listing-state ${p.listed?'is-listed':''}"><i></i>${p.listed?'En vente':p.listingQueued?'Fiche produit en préparation':'À mettre en vente'}</div></div><strong>${stock}<small>prêts</small></strong></div><div class="product-specs"><span><b>${p.grams} g</b> ${p.material.toUpperCase()}</span><span><b>${fastest?time(fastest*60):'—'}</b> machine · profil équilibré</span><span><b>${time(p.finish*60+10)}</b> de travail / pièce</span></div>${lots.length?`<div class="finished-colors">${[...new Set(lots.map(l=>l.colorId))].map(c=>`<span><i style="background:${colorFor(c).hex}"></i>${esc(colorFor(c).name)} <b>${goodsFor(s,p.id,c)}</b></span>`).join('')}</div>`:''}<div class="product-price-row"><label>Mon prix de vente <span><input type="number" min="10" max="120" step="1" value="${p.price}" data-creation-price="${p.id}" aria-label="Prix de vente de ${esc(p.name)}"> €</span></label>${p.listed?`<button class="text-button" data-action="unlist-creation" data-id="${p.id}">Retirer de la vente</button>`:`<button class="button secondary small" data-action="list-creation" data-id="${p.id}" ${p.listingQueued?'disabled':''}>${p.listingQueued?'Fiche en cours…':'Mettre en vente · 15 min'}</button>`}</div><div class="production-controls"><label>Couleur à fabriquer<select data-production-color="${p.id}" aria-label="Couleur à fabriquer pour ${esc(p.name)}">${FILAMENT_COLORS.map(c=>`<option value="${c.id}" ${plan.colorId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><small>${count(available)} g disponibles · ${p.grams} g / pièce</small></label><div><button class="button primary small" data-action="craft-stock" data-id="${p.id}" data-qty="1" ${!machines.length?'disabled':''}>Fabriquer 1</button><button class="button secondary small" data-action="craft-stock" data-id="${p.id}" data-qty="3" ${!machines.length?'disabled':''}>× 3</button></div></div><div class="auto-production-row"><label><input type="checkbox" data-production-auto="${p.id}" ${plan.enabled?'checked':''}><span>Produire si une machine est libre<small>${plan.enabled&&!s.settings.autoCraft?'Réassort en pause dans les consignes.':'Sans acheter de filament juste pour ce réassort.'}</small></span></label><label>Cible<select data-production-target="${p.id}" aria-label="Cible de stock pour ${esc(p.name)}">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${plan.target===n?'selected':''}>${n}</option>`).join('')}</select></label></div><label class="on-demand-row"><input type="checkbox" data-creation-ondemand="${p.id}" ${p.sellToOrder?'checked':''}> Proposer aussi une fabrication à la commande</label>${pending.length?`<div class="craft-jobs">${pending.map(o=>`<div><i class="craft-job-dot ${o.status==='printing'?'is-printing':''}"></i><span>${STATUS[o.status]} · ${colorFor(o.colorId).name}</span><b>${o.status==='printing'?time(o.remaining):''}</b><button data-action="cancel-craft" data-id="${o.id}" aria-label="Annuler cette fabrication">×</button></div>`).join('')}</div>`:''}${available<p.grams?'<button class="text-button creation-restock" data-action="craft-restock" data-id="${p.id}">＋ Ajouter une bobine au panier</button>':''}${!machines.length?'<p class="creation-warning">Une machine adaptée au volume et au profil est nécessaire.</p>':''}</article>`;
 }).join('')}</div>`;
}
